-- Alaska. The state had three stops.
--
-- One dropped: Santa Claus House at North Pole is already here.
--
-- America/Anchorage throughout. Alaska has a second zone, America/Adak, for
-- the Aleutians west of about 169°W, but nothing in this batch is that far
-- out. Anything from Adak or Atka later belongs on it.
--
-- Eleven internal proximity flags, all kept. Skagway's Broadway is four blocks
-- of gold-rush buildings that are each their own museum, and Sitka and
-- Ketchikan are much the same. A town built along one street produces stops
-- twenty metres apart, and that is the town rather than a data problem.
--
-- Worth knowing about routing here. Juneau, Sitka, Ketchikan, Kodiak and much
-- of the southeast are not connected by road to anywhere — the trip planner
-- will refuse those pairs, and now says why rather than blaming the routing
-- service.
--
-- Well sourced: nps.gov leads, then alaska.org and dnr.alaska.gov.
--
-- 133 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Totem Heritage Center', 'totem-heritage-center', 'weird-history', 55.34206, -131.63377, 'Ketchikan', 'AK', 'This city-run center preserves nineteenth-century Tlingit, Haida and Tsimshian poles and carved objects recovered from abandoned village sites. The collection gives travelers a close, museum-based look at original Northwest Coast carving rather than modern replicas alone.', 'open', 'https://www.ketchikanmuseums.org/totem-heritage-center', null, 'America/Anchorage', now()),
  ('Totem Bight State Historical Park', 'totem-bight-state-historical-park', 'weird-history', 55.42045, -131.77288, 'Ketchikan', 'AK', 'A forest trail leads through restored and recreated clan houses and monumental poles on the Tongass Narrows. The state historic park was developed from a New Deal-era effort to preserve and teach traditional Native carving skills.', 'open', 'https://dnr.alaska.gov/parks/aspunits/southeast/totembightshp.htm', null, 'America/Anchorage', now()),
  ('Saxman Totem Park', 'saxman-totem-park', 'weird-history', 55.31897, -131.59814, 'Saxman', 'AK', 'Saxman preserves a dense collection of Tlingit poles, many recreated from historic village carvings, beside a clan house and carving facilities. Cultural programs and interior access are scheduled, while the grounds are viewed under local visitor rules.', 'limited', 'https://www.travelalaska.com/destinations/cities-towns/ketchikan', null, 'America/Anchorage', now()),
  ('Creek Street', 'creek-street', 'weird-history', 55.3424, -131.64189, 'Ketchikan', 'AK', 'Wooden buildings on pilings curve above Ketchikan Creek along the town''s former red-light district. The boardwalk survives as a compact piece of frontier-era architecture with bootlegging and vice history built directly over the water.', 'open', 'https://www.visit-ketchikan.com/things-to-do/creek-street/', null, 'America/Anchorage', now()),
  ('Dolly''s House Museum', 'dollys-house-museum', 'weird-history', 55.34161, -131.64111, 'Ketchikan', 'AK', 'This preserved Creek Street house interprets the life and workplace of Dolly Arthur, one of Ketchikan''s best-known madams. Its small rooms and period furnishings make the city''s former red-light district unusually tangible.', 'limited', 'https://www.visit-ketchikan.com/things-to-do/creek-street/', null, 'America/Anchorage', now()),
  ('Married Man''s Trail', 'married-mans-trail', 'weird-history', 55.34268, -131.6408, 'Ketchikan', 'AK', 'The narrow path above Creek Street is traditionally associated with customers who wanted a less conspicuous route into Ketchikan''s old red-light district. Today it is a lawful public walkway tied to the same bootlegging and vice-era stories as the boardwalk below.', 'open', 'https://www.visit-ketchikan.com/things-to-do/creek-street/', null, 'America/Anchorage', now()),
  ('Tongass Historical Museum', 'tongass-historical-museum', 'museums', 55.34234, -131.6432, 'Ketchikan', 'AK', 'Ketchikan''s city museum covers fishing, mining, Native culture and the rough-edged development of the town around the water. Historic photographs and locally specific objects give context to many of the stranger nearby waterfront stops.', 'open', 'https://www.ketchikanmuseums.org/tongass-historical-museum', null, 'America/Anchorage', now()),
  ('Southeast Alaska Discovery Center', 'southeast-alaska-discovery-center', 'museums', 55.3432, -131.65106, 'Ketchikan', 'AK', 'The Forest Service center interprets the Tongass, Southeast Alaska ecosystems and regional Native cultures through exhibits, films and ranger programs. It is a strong orientation stop for the rainforest, wildlife and human history behind the surrounding OddWay sites.', 'limited', 'https://www.fs.usda.gov/r10/tongass/recreation/southeast-alaska-discovery-center', null, 'America/Anchorage', now()),
  ('Chief Johnson Totem Pole', 'chief-johnson-totem-pole', 'weird-history', 55.34205, -131.64297, 'Ketchikan', 'AK', 'A prominent monumental pole stands near the mouth of Ketchikan Creek in the city''s historic core. The site connects the modern waterfront to Tlingit carving traditions that predate the Gold Rush streets around it.', 'open', 'https://www.travelalaska.com/destinations/cities-towns/ketchikan', null, 'America/Anchorage', now()),
  ('Petroglyph Beach State Historic Site', 'petroglyph-beach-state-historic-site', 'weird-history', 56.48171, -132.39298, 'Wrangell', 'AK', 'Dozens of ancient rock carvings appear along a tidal beach, with spirals, faces and animal-like forms exposed depending on the tide. Visitors should view the carvings without chalking, rubbing or otherwise damaging the stone.', 'open', 'https://dnr.alaska.gov/parks/units/petroglyph.htm', null, 'America/Anchorage', now()),
  ('Chief Shakes Tribal House', 'chief-shakes-tribal-house', 'weird-history', 56.46571, -132.38062, 'Wrangell', 'AK', 'A reconstructed Tlingit clan house stands on Shakes Island amid carved poles and historic cultural features. The house and island preserve the legacy of Chief Shakes and the Stikine Tlingit community and should be visited according to local cultural-access rules.', 'limited', 'https://www.travelalaska.com/destinations/cities-towns/wrangell', null, 'America/Anchorage', now()),
  ('Wrangell Museum at the Nolan Center', 'wrangell-museum-at-the-nolan-center', 'museums', 56.46976, -132.38322, 'Wrangell', 'AK', 'The museum brings together Tlingit history, Russian America, fur trade, gold rush and local objects from one of Alaska''s oldest continuously occupied communities. It gives unusually layered context to a town that changed colonial hands several times.', 'open', 'https://www.wrangell.com/community/nolan-center', null, 'America/Anchorage', now()),
  ('Sandy Beach Petroglyphs & Ancient Fish Traps', 'sandy-beach-petroglyphs-ancient-fish-traps', 'weird-history', 56.80639, -132.91694, 'Petersburg', 'AK', 'Low tides reveal petroglyphs and remnants of ancient intertidal fish traps around Sandy Beach. The features are archaeological resources, so visitors should observe them in place without moving rocks or disturbing cultural material.', 'limited', 'https://www.adfg.alaska.gov/index.cfm?adfg=southeastviewing.petersburgsandybeach', null, 'America/Anchorage', now()),
  ('Sons of Norway Hall', 'sons-of-norway-hall', 'roadside-oddities', 56.81051, -132.95897, 'Petersburg', 'AK', 'This waterfront hall is a visible anchor of Petersburg''s unusually strong Norwegian identity, celebrated with rosemaling, festivals and Scandinavian traditions. Public access depends on events, but the building and surrounding Little Norway district remain a distinctive cultural stop.', 'limited', 'https://www.petersburg.org/', null, 'America/Anchorage', now()),
  ('Clausen Memorial Museum', 'clausen-memorial-museum', 'museums', 56.80634, -132.96964, 'Petersburg', 'AK', 'A small local museum preserves Petersburg''s fishing, cannery, Native and Norwegian-American history. Its community-built collection is especially useful for understanding why this isolated Southeast town looks and feels different from many other Alaska ports.', 'limited', 'https://www.petersburg.org/', null, 'America/Anchorage', now()),
  ('Outlook Park Stave-Church Shelter', 'outlook-park-stave-church-shelter', 'roadside-oddities', 56.8047, -132.9399, 'Petersburg', 'AK', 'A Norwegian stave-church-inspired shelter and overlook turn this roadside park into a compact piece of Scandinavian-themed architecture. It reinforces Petersburg''s ''Little Norway'' identity while overlooking the waterways and mountains beyond town.', 'open', 'https://www.petersburg.org/adventures-in-psg', null, 'America/Anchorage', now()),
  ('Russian Bishop''s House', 'russian-bishops-house', 'weird-history', 57.05143, -135.33104, 'Sitka', 'AK', 'One of the few surviving Russian colonial buildings in North America preserves rooms used by Orthodox Bishop Innocent Veniaminov. National Park Service interpretation connects the house to Russian America, religion, education and Alaska Native communities.', 'limited', 'https://www.nps.gov/sitk/learn/historyculture/russian-bishops-house.htm', null, 'America/Anchorage', now()),
  ('St. Michael''s Cathedral', 'st-michaels-cathedral', 'weird-history', 57.05006, -135.33512, 'Sitka', 'AK', 'The Orthodox cathedral in the center of Sitka is a landmark of the Russian-American era and houses historic icons and church objects. The current building is a reconstruction after the original burned in 1966, so visitors should treat it as an active place of worship rather than a museum-only attraction.', 'limited', 'https://www.oca.org/parishes/oca-ak-sitstm', null, 'America/Anchorage', now()),
  ('Baranof Castle State Historic Site — Castle Hill', 'baranof-castle-state-historic-site-castle-hill', 'weird-history', 57.04865, -135.33798, 'Sitka', 'AK', 'This low hill was the site of Tlingit fortifications, Russian colonial buildings and the 1867 transfer ceremony in which Alaska passed from Russia to the United States. A short public climb reaches the monument and views over Sitka Sound.', 'open', 'https://dnr.alaska.gov/parks/aspunits/southeast/baranofcastleshs.htm', null, 'America/Anchorage', now()),
  ('Sheldon Jackson Museum', 'sheldon-jackson-museum', 'weird-history', 57.05054, -135.32223, 'Sitka', 'AK', 'One of Alaska''s oldest museums holds Native material culture collected across the state, including masks, carvings, clothing and tools from many distinct peoples. The collection is historically important but should also be read critically because much of it was assembled during a colonial missionary period.', 'open', 'https://museums.alaska.gov/sheldon_jackson/sjhome.html', null, 'America/Anchorage', now()),
  ('Sitka National Historical Park Totem Trail', 'sitka-national-historical-park-totem-trail', 'weird-history', 57.04864, -135.31875, 'Sitka', 'AK', 'A rainforest trail displays monumental poles while passing through the landscape of the 1804 Battle of Sitka. The park combines Tlingit history, Russian colonial history and living carving traditions in one walkable site.', 'open', 'https://www.nps.gov/sitk/index.htm', null, 'America/Anchorage', now()),
  ('Battle of Sitka / Russian Memorial', 'battle-of-sitka-russian-memorial', 'weird-history', 57.04736, -135.31093, 'Sitka', 'AK', 'The park landscape marks the 1804 battle between Tlingit defenders and Russian forces and their allies. Interpretation centers the conflict within the larger story of colonial expansion, resistance and the Tlingit departure from the fortified site.', 'open', 'https://www.nps.gov/sitk/learn/historyculture/battle-of-sitka.htm', null, 'America/Anchorage', now()),
  ('Princess Maksoutoff''s Grave', 'princess-maksoutoffs-grave', 'weird-history', 57.05018, -135.33852, 'Sitka', 'AK', 'Behind the Pioneer Home in the Lutheran cemetery is the grave of Princess Maksoutoff, first wife of Alaska''s last Russian-American governor. It is a small but concrete link to Sitka''s final years as the capital of Russian America; visit quietly during lawful cemetery access.', 'limited', 'https://visitsitka.org/member/princess-maksoutoffs-grave', null, 'America/Anchorage', now()),
  ('Alaska Native Brotherhood Hall', 'alaska-native-brotherhood-hall', 'weird-history', 57.05068, -135.34123, 'Sitka', 'AK', 'This waterfront hall is associated with the Alaska Native Brotherhood, founded in 1912 as an important Native civil-rights organization. The historic building is best treated as an exterior history stop unless an authorized public event is underway.', 'roadside', 'https://www.nps.gov/places/alaska-native-brotherhood-hall.htm', null, 'America/Anchorage', now()),
  ('Old Sitka State Historical Park', 'old-sitka-state-historical-park', 'weird-history', 57.12955, -135.37342, 'Sitka', 'AK', 'This site preserves the area of the Russian settlement known as New Archangel''s predecessor, established after the first Russian-Tlingit conflict and destroyed in 1802. Trails and interpretation mark a place where colonial ambitions and Tlingit resistance collided before modern Sitka formed farther south.', 'open', 'https://dnr.alaska.gov/parks/aspunits/southeast/oldsitkashp.htm', null, 'America/Anchorage', now()),
  ('Sitka History Museum', 'sitka-history-museum', 'museums', 57.04954, -135.33787, 'Sitka', 'AK', 'The museum preserves objects and archives spanning Tlingit history, Russian America, territorial Alaska and the modern city. Its locally focused collections help connect the many separate historic layers packed into central Sitka.', 'open', 'https://www.sitkahistory.org/', null, 'America/Anchorage', now()),
  ('The Prospector Statue at Sitka Pioneer Home', 'the-prospector-statue-at-sitka-pioneer-home', 'roadside-oddities', 57.05005, -135.33768, 'Sitka', 'AK', 'A weathered prospector figure stands outside the historic Pioneer Home, creating one of downtown Sitka''s stranger human-scale monuments. The surrounding grounds also place the sculpture beside one of Alaska''s long-running elder-care institutions and the old cemetery landscape.', 'open', 'https://visitsitka.org/', null, 'America/Anchorage', now()),
  ('Alaska State Museum', 'alaska-state-museum', 'museums', 58.29994, -134.41611, 'Juneau', 'AK', 'The state museum holds major collections on Alaska Native cultures, Russian America, mining, maritime history and territorial life. It is one of the best single places to understand the unusual objects and stories scattered across the rest of an Alaska OddWay route.', 'open', 'https://museums.alaska.gov/', null, 'America/Anchorage', now()),
  ('Sealaska Heritage Institute', 'sealaska-heritage-institute', 'weird-history', 58.3004, -134.40686, 'Juneau', 'AK', 'This Tlingit, Haida and Tsimshian cultural center presents monumental art, historic objects and contemporary Northwest Coast work in downtown Juneau. It is operated by a Native organization, making it an important primary cultural source rather than an outsider interpretation of the region.', 'open', 'https://sealaskaheritage.org/', null, 'America/Anchorage', now()),
  ('Juneau-Douglas City Museum', 'juneau-douglas-city-museum', 'museums', 58.30183, -134.41129, 'Juneau', 'AK', 'The city museum focuses on Juneau''s gold rush, governance, Native history and the growth of a capital hemmed between mountains and water. Small-scale exhibits add local context to nearby mine ruins and historic buildings.', 'open', 'https://www.juneau.org/parks-recreation/museum', null, 'America/Anchorage', now()),
  ('Last Chance Mining Museum', 'last-chance-mining-museum', 'weird-history', 58.3056, -134.38448, 'Juneau', 'AK', 'Mining machinery, rail equipment and industrial artifacts fill a surviving compressor building in the old Alaska Juneau Gold Mining Company complex. Its location in a narrow mountain basin makes the hardware feel much closer to an abandoned industrial site than a conventional museum.', 'limited', 'https://www.lastchanceminingmuseum.com/', null, 'America/Anchorage', now()),
  ('Wickersham State Historic Site', 'wickersham-state-historic-site', 'weird-history', 58.30094, -134.41455, 'Juneau', 'AK', 'The former home of judge and Alaska political figure James Wickersham preserves period rooms and material from territorial-era Juneau. The house connects law, politics, mountaineering and early twentieth-century Alaska inside an unusually intact historic residence.', 'limited', 'https://dnr.alaska.gov/parks/aspunits/southeast/wickershamshp.htm', null, 'America/Anchorage', now()),
  ('St. Nicholas Russian Orthodox Church', 'st-nicholas-russian-orthodox-church', 'weird-history', 58.30314, -134.40895, 'Juneau', 'AK', 'This small octagonal Orthodox church was built in the 1890s by local Tlingit Orthodox Christians. Its onion dome and interior icons create an unexpected Russian-influenced landmark amid downtown Juneau''s later American-era buildings.', 'limited', 'https://www.oca.org/parishes/oca-ak-junstn', null, 'America/Anchorage', now()),
  ('Treadwell Mine Glory Hole & Historic Trail', 'treadwell-mine-glory-hole-historic-trail', 'weird-history', 58.2663, -134.3794, 'Douglas', 'AK', 'Trails cross the remains of the once-enormous Treadwell gold-mining complex, including foundations, machinery and the flooded glory-hole area. The site tells the story of an industrial town that largely vanished after mine flooding and collapse in the early twentieth century.', 'open', 'https://treadwellsociety.com/', null, 'America/Anchorage', now()),
  ('AJ Mine Gastineau Mill Tour', 'aj-mine-gastineau-mill-tour', 'weird-history', 58.26592, -134.33349, 'Juneau', 'AK', 'A guided tour enters the remains of Juneau''s hard-rock mining landscape and demonstrates historic milling and mining equipment. Because access is through an operating tour rather than free exploration, reservations and posted safety rules apply.', 'limited', 'https://ajminegastineau.com/', null, 'America/Anchorage', now()),
  ('Evergreen Cemetery', 'evergreen-cemetery', 'weird-history', 58.30462, -134.423, 'Juneau', 'AK', 'Juneau''s historic cemetery contains miners, politicians, pioneers and other figures from the capital''s early eras, including several unusually prominent Alaska names. It is a respectful history stop rather than a paranormal attraction and should be visited only during lawful cemetery access.', 'limited', 'https://www.juneau.org/parks-recreation/cemeteries', null, 'America/Anchorage', now()),
  ('Tahku Whale Sculpture', 'tahku-whale-sculpture', 'roadside-oddities', 58.29912, -134.42644, 'Juneau', 'AK', 'A life-size breaching humpback rises from an artificial pool on the Juneau waterfront, complete with water effects that make the bronze appear to explode from the surface. The oversized sculpture is one of the city''s strongest contemporary roadside-style photo stops.', 'open', 'https://www.traveljuneau.com/', null, 'America/Anchorage', now()),
  ('Hammer Museum', 'hammer-museum', 'museums', 59.23514, -135.44414, 'Haines', 'AK', 'Thousands of hammers, from ordinary hand tools to specialized industrial designs, fill a museum devoted almost entirely to one object category. The giant hammer outside makes the niche collection easy to spot from the street.', 'limited', 'https://www.hammermuseum.org/', null, 'America/Anchorage', now()),
  ('Fort William H. Seward', 'fort-william-h-seward', 'weird-history', 59.22694, -135.44389, 'Haines', 'AK', 'The former U.S. Army post known as Chilkoot Barracks survives as a broad collection of white buildings overlooking Lynn Canal. Most structures have civilian uses today, so it works best as an exterior historic district rather than an abandoned-base exploration site.', 'open', 'https://www.travelalaska.com/destinations/cities-towns/haines', null, 'America/Anchorage', now()),
  ('Haines Sheldon Museum', 'haines-sheldon-museum', 'museums', 59.23566, -135.4452, 'Haines', 'AK', 'The community museum preserves Chilkat Valley history, Tlingit art, pioneer material and local stories in a compact waterfront collection. Its objects provide context for the region''s totem poles, mining history and unusually concentrated eagle culture.', 'limited', 'https://www.sheldonmuseum.org/', null, 'America/Anchorage', now()),
  ('American Bald Eagle Foundation', 'american-bald-eagle-foundation', 'museums', 59.23095, -135.44594, 'Haines', 'AK', 'A natural-history museum and raptor center focuses on Alaska''s birds and wildlife, with live educational ambassadors and taxidermy displays. Haines sits beside one of the world''s best-known seasonal bald-eagle concentrations, giving the collection a strong local reason to exist.', 'limited', 'https://www.baldeagles.org/', null, 'America/Anchorage', now()),
  ('Jilkaat Kwaan Heritage Center', 'jilkaat-kwaan-heritage-center', 'weird-history', 59.39847, -135.89486, 'Klukwan', 'AK', 'Operated in the Tlingit village of Klukwan, the heritage center preserves clan treasures, monumental carvings and the celebrated Whale House collection. Visits should follow posted cultural protocols and seasonal schedules rather than treating the village as an unrestricted attraction.', 'limited', 'https://jilkaatkwaanheritagecenter.org/', null, 'America/Anchorage', now()),
  ('Gold Rush Cemetery', 'gold-rush-cemetery', 'weird-history', 59.47312, -135.289, 'Skagway', 'AK', 'This forest-edge cemetery contains the graves of figures tied to Skagway''s violent Gold Rush years, including con man Jefferson ''Soapy'' Smith and surveyor Frank Reid. The cemetery is public but should be treated respectfully and not as a staged haunted attraction.', 'limited', 'https://www.nps.gov/klgo/learn/historyculture/cemeteries.htm', null, 'America/Anchorage', now()),
  ('Dyea Townsite', 'dyea-townsite', 'weird-history', 59.50271, -135.36, 'Dyea', 'AK', 'Dyea boomed as a competing Klondike gateway before the railroad and a deadly avalanche helped end its brief prominence. Forest and tidal flats now cover much of the vanished town, with trails and scattered remains interpreted by the National Park Service.', 'limited', 'https://www.nps.gov/klgo/learn/historyculture/dyea.htm', null, 'America/Anchorage', now()),
  ('Slide Cemetery', 'slide-cemetery', 'weird-history', 59.50987, -135.36052, 'Dyea', 'AK', 'A small cemetery holds victims of the 1898 avalanche on the Chilkoot Trail, one of the deadliest disasters of the Klondike rush. Its remote setting near Dyea makes the tragedy unusually tangible; visitors should stay on established routes and respect the graves.', 'limited', 'https://www.nps.gov/klgo/learn/historyculture/cemeteries.htm', null, 'America/Anchorage', now()),
  ('Moore House Museum', 'moore-house-museum', 'weird-history', 59.45499, -135.31394, 'Skagway', 'AK', 'The restored Moore House interprets the family that held land at Skagway before thousands of stampeders transformed the valley. Period rooms make the sudden collision between homesteading and Gold Rush boomtown development easier to visualize.', 'limited', 'https://www.nps.gov/klgo/planyourvisit/museums.htm', null, 'America/Anchorage', now()),
  ('Jeff Smith''s Parlor Museum', 'jeff-smiths-parlor-museum', 'weird-history', 59.45401, -135.31797, 'Skagway', 'AK', 'This restored building is associated with Jefferson ''Soapy'' Smith, the confidence man whose organization preyed on Klondike travelers before his death in 1898. National Park Service tours interpret the building and the mythology that grew around Skagway''s most notorious criminal figure.', 'limited', 'https://www.nps.gov/klgo/planyourvisit/museums.htm', null, 'America/Anchorage', now()),
  ('Mascot Saloon Museum', 'mascot-saloon-museum', 'weird-history', 59.45461, -135.3168, 'Skagway', 'AK', 'A restored 1898 saloon preserves the bar, gaming atmosphere and material culture of the Gold Rush entertainment district. Unlike a modern themed bar, the building is interpreted as a museum inside the national historical park.', 'limited', 'https://www.nps.gov/klgo/planyourvisit/museums.htm', null, 'America/Anchorage', now()),
  ('Klondike Gold Rush NHP Visitor Center — Broadway Depot', 'klondike-gold-rush-nhp-visitor-center-broadway-depot', 'weird-history', 59.4535, -135.3185, 'Skagway', 'AK', 'The National Park Service visitor center occupies the historic White Pass & Yukon Route Broadway Depot and anchors Skagway''s Gold Rush district. Exhibits and the park film explain the stampede north before travelers fan out to the town''s smaller historic buildings.', 'limited', 'https://www.nps.gov/klgo/planyourvisit/visitorcenters.htm', null, 'America/Anchorage', now()),
  ('Martin Itjen House', 'martin-itjen-house', 'weird-history', 59.45284, -135.31808, 'Skagway', 'AK', 'This small historic house is associated with Martin Itjen, an early Skagway tourism promoter famous for colorful tours and mechanical showmanship. The National Park Service preserves the relocated building near the waterfront, but interior access is not consistently offered.', 'roadside', 'https://www.nps.gov/klgo/learn/historyculture/itjenhouse.htm', null, 'America/Anchorage', now()),
  ('Arctic Brotherhood Hall', 'arctic-brotherhood-hall', 'roadside-oddities', 59.45402, -135.31819, 'Skagway', 'AK', 'Thousands of pieces of driftwood cover the false front of this 1899 fraternal hall, giving it one of the strangest facades in Alaska. The building now functions as a visitor-oriented landmark, but the exterior itself is the main OddWay draw.', 'open', 'https://www.skagway.com/', null, 'America/Anchorage', now()),
  ('Red Onion Saloon Brothel Museum', 'red-onion-saloon-brothel-museum', 'weird-history', 59.45392, -135.31851, 'Skagway', 'AK', 'The 1898 Red Onion operated as a saloon and brothel during Skagway''s boom years and now interprets that history through scheduled tours. Modern paranormal stories surround the building as well, but those should be treated as lore rather than established fact.', 'limited', 'https://www.redonion1898.com/', null, 'America/Anchorage', now()),
  ('Skagway Museum', 'skagway-museum', 'museums', 59.45571, -135.31178, 'Skagway', 'AK', 'Housed in a distinctive former school and federal building, the city museum preserves Gold Rush, Native, transportation and local civic history. The building''s fortress-like stone lower level and eclectic collection make it more atmospheric than a generic town museum.', 'limited', 'https://www.skagway.org/library/page/skagway-museum', null, 'America/Anchorage', now()),
  ('Chilkoot Trailhead', 'chilkoot-trailhead', 'weird-history', 59.51186, -135.34699, 'Dyea', 'AK', 'The modern trailhead begins the U.S. side of the legendary Chilkoot Trail, where stampeders carried enormous loads toward the Klondike. Even travelers not hiking the full route can stop at the trailhead and connect the landscape to the famous human chain seen in Gold Rush photographs.', 'limited', 'https://www.nps.gov/klgo/planyourvisit/chilkoottrail.htm', null, 'America/Anchorage', now()),
  ('Soapy Smith''s Grave', 'soapy-smiths-grave', 'weird-history', 59.47393, -135.28903, 'Skagway', 'AK', 'The grave of con man Jefferson ''Soapy'' Smith stands in the Gold Rush Cemetery after his death in a waterfront gunfight in 1898. The marker is a specific pilgrimage point within the larger cemetery and should be visited respectfully.', 'limited', 'https://www.nps.gov/klgo/learn/historyculture/cemeteries.htm', null, 'America/Anchorage', now()),
  ('Anchorage Museum', 'anchorage-museum', 'museums', 61.21605, -149.88454, 'Anchorage', 'AK', 'Alaska''s largest museum combines art, history, science and Smithsonian Arctic Studies collections under one roof. Its Native objects, northern technology and Alaska-specific exhibits make it a useful high-density OddWay stop rather than a generic art museum.', 'open', 'https://www.anchoragemuseum.org/', null, 'America/Anchorage', now()),
  ('Alaska Native Heritage Center', 'alaska-native-heritage-center', 'weird-history', 61.23272, -149.71642, 'Anchorage', 'AK', 'The center is a Native-led cultural institution with indoor exhibits and outdoor life-size village sites representing Alaska''s Indigenous peoples. Demonstrations, dance and interpretation emphasize living cultures rather than treating Native history as something that ended in the past.', 'open', 'https://www.alaskanative.net/', null, 'America/Anchorage', now()),
  ('Alaska Aviation Museum', 'alaska-aviation-museum', 'weird-history', 61.17918, -149.97256, 'Anchorage', 'AK', 'Historic bush planes, wreckage, engines and aviation artifacts fill hangars beside Lake Hood, one of the world''s busiest seaplane bases. Alaska''s dependence on aircraft makes the collection especially relevant to the state''s remote OddWay geography.', 'open', 'https://alaskaairmuseum.org/', null, 'America/Anchorage', now()),
  ('Alaska Museum of Science & Nature', 'alaska-museum-of-science-nature', 'museums', 61.22522, -149.80785, 'Anchorage', 'AK', 'Dinosaurs, Ice Age mammals, minerals and Alaska geology share space in a small science museum. Fossils and large skeletons give Anchorage an unexpectedly prehistoric stop far from the state''s more familiar Gold Rush museums.', 'open', 'https://alaskamuseum.org/', null, 'America/Anchorage', now()),
  ('Alaska Law Enforcement Museum', 'alaska-law-enforcement-museum', 'weird-history', 61.21769, -149.88636, 'Anchorage', 'AK', 'This niche museum preserves territorial police, Alaska State Trooper and law-enforcement history through uniforms, equipment, vehicles and case material. Its focus on frontier policing makes it a distinctive counterpart to Alaska''s mining and military museums.', 'limited', 'https://alaskatroopermuseum.com/', null, 'America/Anchorage', now()),
  ('Earthquake Park', 'earthquake-park', 'weird-history', 61.19814, -149.97072, 'Anchorage', 'AK', 'Trails cross land dramatically altered by the magnitude 9.2 Good Friday earthquake of 1964. Interpretive signs explain how entire sections of bluff failed and slid, making invisible geologic processes readable in the modern forest.', 'open', 'https://www.anchorage.net/outdoors/trails-and-local-parks/earthquake-park/', null, 'America/Anchorage', now()),
  ('Oscar Anderson House Museum', 'oscar-anderson-house-museum', 'weird-history', 61.21861, -149.90611, 'Anchorage', 'AK', 'One of Anchorage''s oldest surviving houses is furnished to interpret family life during the city''s early railroad-town years. Its small domestic scale contrasts sharply with the modern city surrounding it.', 'limited', 'https://www.anchoragemuseum.org/visit/oscar-anderson-house-museum/', null, 'America/Anchorage', now()),
  ('Potter Section House State Historical Site', 'potter-section-house-state-historical-site', 'weird-history', 61.05192, -149.79689, 'Anchorage', 'AK', 'A restored Alaska Railroad section house preserves the world of crews who maintained the line through Turnagain Arm. Historic rail equipment and the surviving structure make this a compact transportation-history stop beside the Seward Highway.', 'limited', 'https://dnr.alaska.gov/parks/aspunits/kenai/pottersectionshs.htm', null, 'America/Anchorage', now()),
  ('Alaska Wild Berry Products Chocolate Waterfall', 'alaska-wild-berry-products-chocolate-waterfall', 'roadside-oddities', 61.17316, -149.86245, 'Anchorage', 'AK', 'Inside the candy shop is a towering chocolate-waterfall display built as a deliberately oversized tourist spectacle. It is exactly the kind of harmless commercial oddity that breaks up a route between heavier historic sites.', 'open', 'https://www.alaskawildberryproducts.com/', null, 'America/Anchorage', now()),
  ('Independence Mine State Historical Park', 'independence-mine-state-historical-park', 'weird-history', 61.79, -149.28472, 'Palmer', 'AK', 'Abandoned and restored mining buildings spread across the alpine slopes of Hatcher Pass where the Independence gold operation once housed hundreds of workers. Trails and interpretive areas provide lawful access to the mining landscape without requiring entry into unsafe structures.', 'limited', 'https://dnr.alaska.gov/parks/aspunits/matsu/independencemine.htm', null, 'America/Anchorage', now()),
  ('Musk Ox Farm', 'musk-ox-farm', 'roadside-oddities', 61.63512, -149.12752, 'Palmer', 'AK', 'A nonprofit farm maintains a herd of musk oxen and interprets qiviut, the exceptionally soft underwool harvested from the animals. Guided visitation makes it one of Alaska''s most unusual agricultural stops.', 'limited', 'https://www.muskoxfarm.org/', null, 'America/Anchorage', now()),
  ('Reindeer Farm', 'reindeer-farm', 'roadside-oddities', 61.54061, -149.05878, 'Palmer', 'AK', 'A working farm offers scheduled encounters with reindeer and other northern animals beneath the Chugach Mountains. The domesticated herd turns an Arctic-associated species into an accessible roadside-style experience.', 'limited', 'https://www.reindeerfarm.com/', null, 'America/Anchorage', now()),
  ('Palmer Museum of History & Art', 'palmer-museum-of-history-art', 'museums', 61.59854, -149.11297, 'Palmer', 'AK', 'The museum interprets the 1935 Matanuska Colony project, when federal planners relocated farming families to Alaska. That unusual New Deal experiment shaped Palmer''s street plan, farms and surviving colony architecture.', 'open', 'https://www.palmermuseum.org/', null, 'America/Anchorage', now()),
  ('Colony House Museum', 'colony-house-museum', 'weird-history', 61.59864, -149.10973, 'Palmer', 'AK', 'A restored Matanuska Colony house is furnished to show the daily life of families recruited to farm Alaska during the Depression. The modest home makes one of the nation''s stranger New Deal settlement experiments tangible.', 'limited', 'https://www.palmerhistoricalsociety.org/', null, 'America/Anchorage', now()),
  ('Iditarod Trail Sled Dog Race Headquarters', 'iditarod-trail-sled-dog-race-headquarters', 'weird-history', 61.58173, -149.45254, 'Wasilla', 'AK', 'Race exhibits, trophies, photographs and sled-dog history are concentrated at the headquarters of the modern Iditarod. The stop links the famous race to Alaska''s much older tradition of winter trail travel.', 'open', 'https://iditarod.com/', null, 'America/Anchorage', now()),
  ('Knik Museum & Mushers Hall of Fame', 'knik-museum-mushers-hall-of-fame', 'weird-history', 61.45734, -149.73013, 'Knik', 'AK', 'The museum stands in what remains of Knik, once a larger trading and transportation center before the railroad shifted activity elsewhere. Exhibits on mushing and the Iditarod share space with the remnants of a near-vanished town.', 'limited', 'https://knikmuseum.org/', null, 'America/Anchorage', now()),
  ('Museum of Alaska Transportation and Industry', 'museum-of-alaska-transportation-and-industry', 'museums', 61.57768, -149.54472, 'Wasilla', 'AK', 'Aircraft, locomotives, tractors, military machines and industrial equipment sprawl across this outdoor-and-indoor collection. The scale and variety make it feel more like a graveyard of northern machinery than a conventional transportation museum.', 'limited', 'https://www.museumofalaska.org/', null, 'America/Anchorage', now()),
  ('Nagley''s Store', 'nagleys-store', 'weird-history', 62.32313, -150.11286, 'Talkeetna', 'AK', 'The historic general-store site became nationally famous for the town''s honorary feline ''mayors,'' beginning with Stubbs. The current business still functions as a real store while preserving Talkeetna''s deliberately eccentric frontier-town identity.', 'open', 'https://www.alaska.org/detail/nagleys-store', null, 'America/Anchorage', now()),
  ('Talkeetna Historical Society Museum', 'talkeetna-historical-society-museum', 'museums', 62.32251, -150.11386, 'Talkeetna', 'AK', 'Historic school buildings hold climbing, railroad and town artifacts, including material tied to Denali expeditions. The museum helps explain why tiny Talkeetna became both a mountaineering base and a center of Alaska eccentricity.', 'limited', 'https://www.talkeetnamuseum.org/', null, 'America/Anchorage', now()),
  ('Fairview Inn', 'fairview-inn', 'weird-history', 62.32325, -150.11333, 'Talkeetna', 'AK', 'This long-running inn and bar is tied to Alaska railroad history and the story that President Warren G. Harding ate here shortly before his death in 1923. Its walls of historic photographs and rough frontier atmosphere make it a living-history stop rather than a preserved museum.', 'open', 'https://www.alaska.org/detail/fairview-inn', null, 'America/Anchorage', now()),
  ('Anton Anderson Memorial Tunnel', 'anton-anderson-memorial-tunnel', 'roadside-oddities', 60.78896, -148.80395, 'Whittier', 'AK', 'The 2.5-mile tunnel through Maynard Mountain is shared by one-lane road traffic and trains, with vehicles moving through on a timed schedule. It is the only land route into Whittier and one of the state''s strangest pieces of transportation infrastructure.', 'limited', 'https://dot.alaska.gov/creg/whittiertunnel/index.shtml', null, 'America/Anchorage', now()),
  ('Begich Towers', 'begich-towers', 'roadside-oddities', 60.77218, -148.68505, 'Whittier', 'AK', 'A huge Cold War-era apartment building houses a large share of Whittier''s population along with community services. The concentration of daily town life inside one structure has made the building central to Whittier''s reputation as an unusually vertical Alaska community.', 'roadside', 'https://www.alaska.org/destination/whittier', null, 'America/Anchorage', now()),
  ('Buckner Building', 'buckner-building', 'weird-history', 60.77463, -148.67502, 'Whittier', 'AK', 'The enormous abandoned military building once contained housing, recreation and services for thousands of people during Whittier''s Cold War development. It is unsafe and not an invitation to enter; OddWay should route only to lawful exterior viewpoints.', 'roadside', 'https://www.alaska.org/detail/whittier-historic-walking-tour', null, 'America/Anchorage', now()),
  ('Roundhouse at Alyeska Museum', 'roundhouse-at-alyeska-museum', 'museums', 60.96167, -149.08056, 'Girdwood', 'AK', 'Alaska''s only mountaintop museum occupies the historic Roundhouse at the upper tram terminal on Mount Alyeska. The octagonal ski building preserves Girdwood and resort history at an elevation reached by aerial tram rather than ordinary street access.', 'limited', 'https://roundhouseatalyeska.org/', null, 'America/Anchorage', now()),
  ('Portage Ghost Town & Ghost Forest', 'portage-ghost-town-ghost-forest', 'weird-history', 60.837, -148.985, 'Portage', 'AK', 'The 1964 Good Friday earthquake dropped the Portage area several feet, allowing salt water to kill forests and force the community''s abandonment. Bleached ghost trees and remnants can be seen from lawful roadside areas; the tidal, boggy former townsite should not be treated as free-roam terrain.', 'roadside', 'https://www.alaska.org/destination/portage', null, 'America/Anchorage', now()),
  ('Fort Kenay Replica', 'fort-kenay-replica', 'weird-history', 60.5543, -151.2589, 'Kenai', 'AK', 'A reconstructed Russian-era trading post interprets the fortified settlement that preceded modern Kenai. The replica provides a physical reference point for the fur-trade and colonial history concentrated in Old Town Kenai.', 'limited', 'https://www.kenaichamber.org/visitor-center', null, 'America/Anchorage', now()),
  ('Holy Assumption of the Virgin Mary Russian Orthodox Church', 'holy-assumption-of-the-virgin-mary-russian-orthodox-church', 'weird-history', 60.55297, -151.26761, 'Kenai', 'AK', 'This National Historic Landmark is one of Alaska''s oldest standing Orthodox churches and remains an active congregation. Its icons, cemetery and Old Town setting preserve a direct architectural link to Russian America and Dena''ina history.', 'limited', 'https://www.oca.org/parishes/oca-ak-kendvm', null, 'America/Anchorage', now()),
  ('St. Nicholas Memorial Chapel', 'st-nicholas-memorial-chapel', 'weird-history', 60.55334, -151.26971, 'Kenai', 'AK', 'The 1906 chapel honors early Orthodox missionaries and stands near the site of Kenai''s first church and Russian trading post. Local history also credits the priests it commemorates with helping bring smallpox vaccination to Dena''ina communities.', 'limited', 'https://www.alaska.org/detail/saint-nicholas-memorial-chapel', null, 'America/Anchorage', now()),
  ('Soldotna Historical Society Museum', 'soldotna-historical-society-museum', 'museums', 60.47685, -151.08781, 'Soldotna', 'AK', 'A cluster of historic log buildings preserves homesteading, school and community life from Soldotna''s relatively recent settlement era. The outdoor village format makes the museum feel like a relocated frontier neighborhood.', 'limited', 'https://soldotnahistoricalsociety.org/', null, 'America/Anchorage', now()),
  ('Transfiguration of Our Lord Russian Orthodox Church', 'transfiguration-of-our-lord-russian-orthodox-church', 'weird-history', 60.05052, -151.66502, 'Ninilchik', 'AK', 'The small Orthodox church and hillside cemetery overlook Cook Inlet from the old village of Ninilchik. Onion domes, wooden architecture and generations of graves preserve the community''s Russian and Alaska Native heritage.', 'limited', 'https://www.oca.org/parishes/oca-ak-nintol', null, 'America/Anchorage', now()),
  ('Pratt Museum', 'pratt-museum', 'museums', 59.64501, -151.5496, 'Homer', 'AK', 'The Pratt combines natural history, Alaska Native culture, homesteading and marine life in a museum rooted specifically in Kachemak Bay. Its blend of ecology and human history makes it a strong interpretation stop before exploring the Homer Spit and surrounding coast.', 'open', 'https://www.prattmuseum.org/', null, 'America/Anchorage', now()),
  ('Homer Seafarer''s Memorial', 'homer-seafarers-memorial', 'weird-history', 59.60066, -151.419, 'Homer', 'AK', 'A waterfront monument on the Homer Spit honors fishermen and mariners lost at sea. The bronze mariner, memorial plaques and annual blessing of the fleet turn the site into a sober reminder of the danger behind Alaska''s fishing culture.', 'open', 'https://www.alaska.org/detail/seafarers-memorial', null, 'America/Anchorage', now()),
  ('Salty Dawg Saloon', 'salty-dawg-saloon', 'weird-history', 59.60187, -151.4215, 'Homer', 'AK', 'This tiny historic saloon on the Homer Spit is covered inside with thousands of signed dollar bills and maritime memorabilia. The building''s roots, rough wood interior and wall-to-wall notes make it one of Alaska''s most recognizable living roadside curiosities.', 'open', 'https://www.saltydawgsaloon.com/', null, 'America/Anchorage', now()),
  ('Kilcher Homestead Living Museum', 'kilcher-homestead-living-museum', 'weird-history', 59.71721, -151.31026, 'Homer', 'AK', 'The Kilcher family homestead preserves cabins, fields and stories from mid-twentieth-century settlement outside Homer. Visits are arranged rather than assumed, so OddWay should direct travelers through current tour information instead of treating the property as open land.', 'limited', 'https://www.alaska.org/detail/kilcher-family-homestead', null, 'America/Anchorage', now()),
  ('Alaska Islands & Ocean Visitor Center', 'alaska-islands-ocean-visitor-center', 'museums', 59.64114, -151.53998, 'Homer', 'AK', 'The federal visitor center interprets the Alaska Maritime National Wildlife Refuge, seabird colonies and the remote islands stretching far into the Aleutians. Exhibits turn places most travelers can never physically reach into a concentrated natural-history stop.', 'open', 'https://www.fws.gov/refuge/alaska-maritime/visit-us', null, 'America/Anchorage', now()),
  ('Iditarod National Historic Trail Mile 0', 'iditarod-national-historic-trail-mile-0', 'weird-history', 60.10168, -149.43608, 'Seward', 'AK', 'A marker in Seward identifies the southern origin of the historic overland trail system that ultimately connected communities toward Nome. It links the modern Iditarod name to freight, mail and winter travel long before the famous race existed.', 'open', 'https://www.blm.gov/programs/national-conservation-lands/alaska/iditarod', null, 'America/Anchorage', now()),
  ('Seward Community Library & Museum', 'seward-community-library-museum', 'museums', 60.10257, -149.43768, 'Seward', 'AK', 'The museum interprets Seward''s railroad, Indigenous, maritime and 1964 earthquake history inside a striking modern public building. Its earthquake material is especially useful context for the reshaped waterfront outside.', 'open', 'https://www.cityofseward.us/departments/library-museum', null, 'America/Anchorage', now()),
  ('Fort McGilvray at Caines Head', 'fort-mcgilvray-at-caines-head', 'weird-history', 59.98674, -149.38967, 'Seward', 'AK', 'Concrete gun emplacements and military remains survive high above Resurrection Bay from the World War II defense of Seward. Reaching the site requires a strenuous route affected by tides, weather and trail conditions, so it is a destination hike rather than a casual roadside ruin.', 'limited', 'https://dnr.alaska.gov/parks/aspunits/kenai/cainesheadsra.htm', null, 'America/Anchorage', now()),
  ('Valdez Museum', 'valdez-museum', 'museums', 61.12903, -146.36018, 'Valdez', 'AK', 'Valdez''s main museum covers Indigenous history, gold-rush transportation, the 1964 earthquake, the oil pipeline and the Exxon Valdez era. Few towns have been rebuilt and transformed as many times, giving the collection an unusually dramatic local scope.', 'open', 'https://www.valdezmuseum.org/', null, 'America/Anchorage', now()),
  ('Remembering Old Valdez Exhibit', 'remembering-old-valdez-exhibit', 'weird-history', 61.12542, -146.36078, 'Valdez', 'AK', 'A dedicated Valdez Museum exhibit focuses on the original town destroyed by the 1964 earthquake and the decision to relocate the community several miles away. Photographs and artifacts turn the vanished town into more than an empty shoreline site.', 'limited', 'https://www.valdezmuseum.org/', null, 'America/Anchorage', now()),
  ('Maxine & Jesse Whitney Museum', 'maxine-jesse-whitney-museum', 'museums', 61.13394, -146.35216, 'Valdez', 'AK', 'A private collection donated to Prince William Sound College includes Alaska Native art, natural-history specimens, ivory and an eclectic range of northern artifacts. The dense collection has the feel of an old-style cabinet museum rather than a single-theme institution.', 'limited', 'https://www.pwscc.edu/about/whitney-museum/', null, 'America/Anchorage', now()),
  ('Old Valdez Townsite', 'old-valdez-townsite', 'weird-history', 61.11567, -146.26517, 'Valdez', 'AK', 'The original Valdez townsite was abandoned after the 1964 earthquake left the waterfront dangerously unstable. Roads, markers and open ground preserve the location of a community that was physically moved to a safer site several miles away.', 'open', 'https://www.valdezalaska.org/discover/history/', null, 'America/Anchorage', now()),
  ('Keystone Canyon Railroad Tunnel', 'keystone-canyon-railroad-tunnel', 'weird-history', 61.0842, -145.89322, 'Valdez', 'AK', 'A hand-cut tunnel in Keystone Canyon is a remnant of an early railroad race to reach Alaska''s copper country. A violent feud helped halt the project, leaving the unfinished bore beside the Richardson Highway as a visible piece of abandoned infrastructure.', 'roadside', 'https://www.hmdb.org/m.asp?m=49609', null, 'America/Anchorage', now()),
  ('Worthington Glacier State Recreation Site', 'worthington-glacier-state-recreation-site', 'roadside-oddities', 61.1679, -145.70989, 'Valdez', 'AK', 'One of Alaska''s most road-accessible glaciers can be viewed from the Richardson Highway recreation site. Current trail conditions can restrict movement beyond the main viewing area, so travelers should follow state-posted closures rather than approaching unstable ice on their own.', 'limited', 'https://dnr.alaska.gov/parks/aspunits/kenai/worthingtonglacier.htm', null, 'America/Anchorage', now()),
  ('Kuskulana River Bridge', 'kuskulana-river-bridge', 'roadside-oddities', 61.48871, -144.01548, 'Chitina', 'AK', 'The narrow former Copper River & Northwestern Railway bridge carries McCarthy Road high over the Kuskulana River gorge. Its early twentieth-century steelwork and exposed setting make the crossing itself one of the road''s most memorable historic artifacts.', 'open', 'https://www.nps.gov/wrst/planyourvisit/mccarthy-road.htm', null, 'America/Anchorage', now()),
  ('Gilahina Trestle', 'gilahina-trestle', 'weird-history', 61.43861, -143.71778, 'Chitina', 'AK', 'A huge timber railroad trestle stands in partial ruin beside McCarthy Road, built quickly to carry copper trains across a difficult drainage. The surviving framework is viewed from lawful roadside areas rather than climbed or entered.', 'roadside', 'https://www.alaska.org/detail/gilahina-trestle', null, 'America/Anchorage', now()),
  ('Chitina Ranger Station & Orr Stage Cabin', 'chitina-ranger-station-orr-stage-cabin', 'weird-history', 61.5159, -144.4382, 'Chitina', 'AK', 'A historic log cabin and ranger contact point recall the stage, railroad and early road connections that fed the Copper River mining region. It is a useful transition stop before the much rougher road toward McCarthy and Kennecott.', 'limited', 'https://www.nps.gov/wrst/planyourvisit/visitor-centers.htm', null, 'America/Anchorage', now()),
  ('McCarthy-Kennicott Historical Museum', 'mccarthy-kennicott-historical-museum', 'museums', 61.43145, -142.9146, 'McCarthy', 'AK', 'The volunteer museum occupies a former Copper River & Northwestern Railway depot and displays mining, railroad and town artifacts. A model of historic McCarthy and material from the Kennecott mines make it the best compact orientation point for the remote district.', 'limited', 'https://mccarthykennicotthistoricalmuseum.com/', null, 'America/Anchorage', now()),
  ('McCarthy Historic District', 'mccarthy-historic-district', 'weird-history', 61.43333, -142.92167, 'McCarthy', 'AK', 'McCarthy grew as the less-regulated service town outside the company-controlled Kennecott mining settlement. Historic buildings, footpaths and surviving businesses preserve the feeling of a boomtown that nearly disappeared after the mines closed.', 'limited', 'https://www.nps.gov/wrst/learn/historyculture/historic-places.htm', null, 'America/Anchorage', now()),
  ('Kennecott Mines National Historic Landmark', 'kennecott-mines-national-historic-landmark', 'weird-history', 61.48105, -142.88523, 'Kennicott', 'AK', 'The enormous red mill buildings and company town of Kennecott survive beneath the mountains where rich copper ore was processed from 1911 to 1938. National Park Service trails and authorized tours allow visitors to experience the industrial ghost town without entering unstable closed structures.', 'limited', 'https://www.nps.gov/places/kennecott-mines.htm', null, 'America/Anchorage', now()),
  ('University of Alaska Museum of the North', 'university-of-alaska-museum-of-the-north', 'museums', 64.85895, -147.8422, 'Fairbanks', 'AK', 'This major northern museum combines Alaska Native collections, fossils, wildlife, art and research specimens in a striking hilltop building. Mammoths, ancient animals and objects from across an enormous state make it one of Alaska''s richest single-stop collections.', 'open', 'https://www.uaf.edu/museum/', null, 'America/Anchorage', now()),
  ('Gold Dredge 8', 'gold-dredge-8', 'weird-history', 64.93832, -147.65609, 'Fairbanks', 'AK', 'A preserved bucket-line gold dredge anchors a tour of Interior mining history north of Fairbanks. Visitors can see the giant machine up close and learn how industrial placer mining reshaped frozen ground at a scale far beyond hand panning.', 'limited', 'https://golddredge8.com/', null, 'America/Anchorage', now()),
  ('Trans-Alaska Pipeline Viewing Point', 'trans-alaska-pipeline-viewing-point', 'roadside-oddities', 64.91945, -147.6214, 'Fairbanks', 'AK', 'A public pull-off north of Fairbanks lets travelers walk directly beneath an elevated section of the Trans-Alaska Pipeline and inspect interpretive displays. The exposed silver pipe turns one of the state''s biggest industrial systems into a literal roadside attraction.', 'open', 'https://www.alaska.org/detail/trans-alaska-pipeline-viewpoint', null, 'America/Anchorage', now()),
  ('Pioneer Park', 'pioneer-park', 'weird-history', 64.8394, -147.77427, 'Fairbanks', 'AK', 'Historic cabins, museums, mining equipment and relocated buildings form a deliberately assembled frontier town inside a city park. The mix of authentic structures and staged heritage attractions creates an unusually dense concentration of Alaska curiosities.', 'open', 'https://www.explorefairbanks.com/explore-the-area/fairbanks/pioneer-park/', null, 'America/Anchorage', now()),
  ('SS Nenana', 'ss-nenana', 'weird-history', 64.83865, -147.77236, 'Fairbanks', 'AK', 'This enormous wooden sternwheeler once carried passengers and freight on Alaska''s river system and now rests permanently at Pioneer Park. It is one of the last surviving large wooden boats of its kind and reads almost like a landlocked shipwreck.', 'limited', 'https://www.explorefairbanks.com/explore-the-area/fairbanks/pioneer-park/', null, 'America/Anchorage', now()),
  ('Fountainhead Antique Auto Museum', 'fountainhead-antique-auto-museum', 'museums', 64.86037, -147.71379, 'Fairbanks', 'AK', 'Dozens of rare pre-World War II automobiles are paired with period clothing and Alaska motoring history. The polished machines are particularly strange in a state where early transportation is more often associated with dog teams, boats and bush planes.', 'limited', 'https://www.fountainheadmuseum.com/', null, 'America/Anchorage', now()),
  ('Aurora Ice Museum', 'aurora-ice-museum', 'roadside-oddities', 65.05391, -146.05975, 'Chena Hot Springs', 'AK', 'A year-round ice environment contains carved rooms, sculptures and an ice bar kept below freezing even in summer. The attraction uses roughly a thousand tons of local ice, producing a surreal frozen interior beside a hot-springs resort.', 'limited', 'https://chenahotsprings.com/aurora-ice-museum/', null, 'America/Anchorage', now()),
  ('Alaska Highway End — Mile 1422 Marker', 'alaska-highway-end-mile-1422-marker', 'weird-history', 64.03787, -145.73007, 'Delta Junction', 'AK', 'A large marker commemorates the traditional end of the Alaska Highway at Delta Junction after its wartime construction from Canada. The sign transforms an otherwise abstract milepost into a concrete endpoint for one of North America''s most famous long-distance roads.', 'open', 'https://www.travelalaska.com/destinations/cities-towns/delta-junction', null, 'America/Anchorage', now()),
  ('Sullivan Roadhouse Historical Museum', 'sullivan-roadhouse-historical-museum', 'museums', 64.03559, -145.73088, 'Delta Junction', 'AK', 'A relocated early-twentieth-century roadhouse preserves the kind of isolated lodging used by travelers on Alaska''s pre-highway trails. Period rooms and the log building itself evoke an era when overland travel depended on widely spaced shelter stops.', 'limited', 'https://www.deltachamber.org/sullivan-roadhouse', null, 'America/Anchorage', now()),
  ('Arctic Circle Sign — Dalton Highway', 'arctic-circle-sign-dalton-highway', 'roadside-oddities', 66.55582, -150.8111, 'Dalton Highway', 'AK', 'A large roadside sign marks the point where the Dalton Highway crosses the Arctic Circle at roughly 66 degrees 33 minutes north. The location is remote, has limited services and requires serious road preparation, but it provides a precise physical marker for an otherwise invisible latitude line.', 'roadside', 'https://www.blm.gov/visit/arctic-circle-campground', null, 'America/Anchorage', now()),
  ('Arctic Interagency Visitor Center', 'arctic-interagency-visitor-center', 'museums', 67.25263, -150.18564, 'Coldfoot', 'AK', 'A federal visitor center in the Brooks Range interprets Arctic ecology, public lands and the Dalton Highway corridor. Its remote position roughly 260 road miles north of Fairbanks makes simply reaching the building part of the OddWay experience.', 'limited', 'https://www.blm.gov/visit/arctic-interagency-visitor-center', null, 'America/Anchorage', now()),
  ('Carrie M. McLain Memorial Museum', 'carrie-m-mclain-memorial-museum', 'museums', 64.49839, -165.40303, 'Nome', 'AK', 'Nome''s city museum interprets Bering Strait cultures, gold mining, transportation and community life through immersive exhibits such as a miner''s tent, dredge setting and Inupiat skin-boat display. It is a strong base for understanding the far-western stops that cannot be reached by Alaska''s road system.', 'open', 'https://www.nomealaska.org/1278/Carrie-M-McLain-Memorial-Museum', null, 'America/Anchorage', now()),
  ('Whale Bone Arch', 'whale-bone-arch', 'roadside-oddities', 71.29953, -156.7714, 'Utqiagvik', 'AK', 'Two immense bowhead whale jawbones form an arch on the Arctic Ocean shoreline, reflecting the central role of subsistence whaling in Iñupiat culture. The structure is a community landmark, not a generic photo prop, so visitors should approach it with respect for local traditions.', 'open', 'https://www.alaska.org/detail/whale-bone-arch', null, 'America/Anchorage', now()),
  ('Kodiak Military History Museum', 'kodiak-military-history-museum', 'weird-history', 57.83645, -152.35292, 'Kodiak', 'AK', 'A museum inside a World War II-era bunker interprets the coastal defenses built after war reached Alaska. Concrete gun positions and military artifacts remain embedded in the surrounding Fort Abercrombie landscape.', 'limited', 'https://www.kodiakmilitaryhistorymuseum.com/', null, 'America/Anchorage', now()),
  ('Kodiak History Museum', 'kodiak-history-museum', 'weird-history', 57.78778, -152.40333, 'Kodiak', 'AK', 'The museum occupies the Russian-American Magazin, one of Alaska''s oldest surviving structures and a former fur-trade warehouse. Exhibits trace Alutiiq, Russian, American and commercial history inside the artifact-rich building itself.', 'open', 'https://kodiakhistorymuseum.org/', null, 'America/Anchorage', now()),
  ('Alutiiq Museum', 'alutiiq-museum', 'weird-history', 57.78861, -152.40267, 'Kodiak', 'AK', 'A Native-led museum and archaeological repository preserves Sugpiaq/Alutiiq history, language, art and excavated material from the Kodiak Archipelago. It is the strongest primary cultural source for interpreting the island''s much older human history.', 'open', 'https://alutiiqmuseum.org/museum/visit/', null, 'America/Anchorage', now()),
  ('Fort Abercrombie WWII Ruins', 'fort-abercrombie-wwii-ruins', 'weird-history', 57.83114, -152.35574, 'Kodiak', 'AK', 'Concrete bunkers, gun emplacements and foundations remain along the cliffs of Fort Abercrombie State Historical Park. Trails allow lawful exploration of the coastal defense landscape while unstable or closed structures should be respected.', 'open', 'https://dnr.alaska.gov/parks/aspunits/kodiak/fortabercrombieshp.htm', null, 'America/Anchorage', now()),
  ('Holy Resurrection Cathedral', 'holy-resurrection-cathedral', 'weird-history', 57.79, -152.40722, 'Kodiak', 'AK', 'Kodiak''s Orthodox cathedral preserves the legacy of Russian America and the canonized missionary St. Herman of Alaska. The active church and its icons make it a living religious site rather than a frozen colonial relic.', 'limited', 'https://www.oca.org/parishes/oca-ak-kodhrc', null, 'America/Anchorage', now()),
  ('Aleutian World War II National Historic Area Visitor Center', 'aleutian-world-war-ii-national-historic-area-visitor-center', 'weird-history', 53.9143, -166.5197, 'Unalaska', 'AK', 'The National Park Service visitor center interprets the Aleutian campaign, Japanese attacks and occupation, and the forced wartime relocation of Unangax̂ people. The center is seasonal with more limited winter access, reflecting the remoteness of the history it preserves.', 'limited', 'https://www.nps.gov/aleu/planyourvisit/visitorcenters.htm', null, 'America/Anchorage', now()),
  ('Fort Schwatka', 'fort-schwatka', 'weird-history', 53.91802, -166.51192, 'Unalaska', 'AK', 'World War II gun positions and fortifications survive high above Dutch Harbor at one of the most dramatic military sites in the Aleutians. The land has access requirements and weather exposure, so visitors must follow local permits and never treat bunkers as unrestricted urbex territory.', 'limited', 'https://www.nps.gov/aleu/learn/historyculture/fort-schwatka.htm', null, 'America/Anchorage', now()),
  ('Museum of the Aleutians', 'museum-of-the-aleutians', 'museums', 53.88192, -166.54916, 'Unalaska', 'AK', 'The museum preserves Unangax̂ archaeology, Russian-American history, fishing culture and World War II material from the Aleutian chain. Its collections provide essential local context for a region where many historic sites are remote, restricted or accessible only by boat and air.', 'limited', 'https://www.museumofthealeutians.org/', null, 'America/Anchorage', now()),
  ('Holy Ascension Cathedral', 'holy-ascension-cathedral', 'weird-history', 53.87547, -166.53634, 'Unalaska', 'AK', 'The historic Orthodox cathedral is a National Historic Landmark reflecting centuries of Russian and Unangax̂ religious history in the Aleutians. It remains an active church, so interior visits should follow congregation schedules and respectful access rules.', 'limited', 'https://www.oca.org/parishes/oca-ak-unahak', null, 'America/Anchorage', now()),
  ('Bering Land Bridge National Preserve Heritage Center', 'bering-land-bridge-national-preserve-heritage-center', 'museums', 64.49792, -165.40842, 'Nome', 'AK', 'This National Park Service center interprets the Bering Land Bridge, Arctic archaeology, geology and the living communities of the Seward Peninsula. It gives travelers a physical portal into a vast preserve that has no road-connected visitor center inside its boundaries.', 'limited', 'https://www.nps.gov/bela/planyourvisit/basicinfo.htm', null, 'America/Anchorage', now()),
  ('Last Train to Nowhere', 'last-train-to-nowhere', 'weird-history', 64.54605, -164.43632, 'Nome', 'AK', 'Three rusting steam locomotives sit beside the Nome-Council Road, remnants of an ambitious early railroad that never fulfilled its larger plans. A viewing area allows travelers to see the machines without climbing on unstable equipment or crossing private ground.', 'roadside', 'https://www.alaska.org/detail/the-last-train-to-nowhere', null, 'America/Anchorage', now()),
  ('Ketchikan Ghost Walk — Alaska Ghosts & Legends', 'ketchikan-ghost-walk-alaska-ghosts-legends', 'haunted', 55.34143, -131.6472, 'Ketchikan', 'AK', 'This scheduled walking tour uses downtown Ketchikan and Creek Street to tell local ghost stories, Alaska Triangle lore and regional creature legends. It is an operating, bookable experience rather than an invitation to enter abandoned property, with current tours meeting at The Rock monument.', 'limited', 'https://www.americanghostwalks.com/alaska/ketchikan/ketchikan-ghost-walk', null, 'America/Anchorage', now()),
  ('Golden North Hotel — Scary Mary Legend', 'golden-north-hotel-scary-mary-legend', 'haunted', 59.45431, -135.31745, 'Skagway', 'AK', 'The onion-domed former Golden North Hotel is tied to Skagway''s long-running ''Scary Mary'' ghost legend about a woman said to have died while waiting for a prospector to return. The building no longer operates as a hotel and now houses businesses, so the haunting should be presented as folklore and access limited to lawful public areas.', 'limited', 'https://www.nps.gov/articles/khns-golden-north.htm', null, 'America/Anchorage', now()),
  ('Alaskan Hotel & Bar', 'alaskan-hotel-bar', 'haunted', 58.30028, -134.405, 'Juneau', 'AK', 'Operating since 1913, this late-Victorian Gold Rush-era hotel preserves a bordello-era past and openly acknowledges its reputation among ghost hunters. It remains a functioning 21+ hotel and bar, so any paranormal claims should be framed as guest stories and local lore rather than fact. History: https://www.thealaskanhotel.com/history/', 'open', 'https://www.thealaskanhotel.com/', null, 'America/Anchorage', now()),
  ('Historic Anchorage Hotel', 'historic-anchorage-hotel', 'haunted', 61.21889, -149.89167, 'Anchorage', 'AK', 'The operating historic hotel maintains its own ghost log and promotes stories tied to unexplained sightings and the unsolved 1921 killing of Anchorage police chief John ''Black Jack'' Sturgus nearby. Because the property itself presents the haunted history, it is a strong lawful paranormal stop without relying only on third-party legend sites.', 'open', 'https://www.historicanchoragehotel.com/our-history.htm', null, 'America/Anchorage', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as alaska from public.stops where state = 'AK';
